-- ~/.config/nvim/lua/plugins/colorscheme.lua — added on top of the LazyVim starter.
-- gruvbox.nvim with its palette remapped to the desktop's colours: on the dark theme ink
-- ground and paper text (gruvbox's dark/bright colours), on the light theme paper ground
-- and ink text (its light/faded colours). 'background' is never set here: Neovim asks foot
-- which ground it has, and foot tells it again when kawa-theme switches (DEC mode 2031),
-- so open editors follow the desktop. Generated by tools/build-themes.py; edit the palette there.
return {
  {
    "ellisonleao/gruvbox.nvim",
    priority = 1000,
    -- the line under the cursor: the palette's surface on both grounds (gruvbox would take
    -- the light theme's text colour for it there — far heavier on paper than on ink)
    init = function()
      vim.api.nvim_create_autocmd("ColorScheme", {
        group = vim.api.nvim_create_augroup("kawa_cursorline", { clear = true }),
        pattern = "gruvbox",
        callback = function()
          local bg = vim.o.background == "light" and "#dcd2b8" or "#161411"
          vim.api.nvim_set_hl(0, "CursorLine", { bg = bg })
        end,
      })
    end,
    opts = {
      contrast = "hard",
      palette_overrides = {
        dark0_hard = "#0f0e0c", dark0 = "#0f0e0c", dark0_soft = "#161411",
        dark1 = "#161411", dark2 = "#1f1c18", dark3 = "#2b2721", dark4 = "#3d372f",
        gray = "#7b7365",
        light0_hard = "#e9e1cb", light0 = "#ece3cc", light1 = "#cfc3a6", light2 = "#b8ad92",
        light3 = "#a0957c", light4 = "#8a8170",
        bright_red = "#d0583a", bright_green = "#a8b46f", bright_yellow = "#e3b866",
        bright_blue = "#7f9dbd", bright_purple = "#ab96c2", bright_aqua = "#7fb8b0",
        bright_orange = "#d07a45",
        neutral_red = "#d64b4b", neutral_yellow = "#d29f45",
        -- the light theme's accents, deepened to read on paper
        faded_red = "#a8342a", faded_green = "#5c682d", faded_yellow = "#845b0f",
        faded_blue = "#3f6185", faded_purple = "#6f5a8a", faded_aqua = "#2f6e67",
        faded_orange = "#a8551f",
      },
    },
  },
  { "LazyVim/LazyVim", opts = { colorscheme = "gruvbox" } },
  -- the statusline in the same colours (lualine's own "gruvbox" theme has gruvbox's stock
  -- ones): made from the palette for the ground Neovim has, and again when that changes
  {
    "nvim-lualine/lualine.nvim",
    opts = function(_, opts)
      local P = {
        dark = { ground = "#0f0e0c", bar = "#161411", key = "#1f1c18", text = "#cfc3a6", muted = "#877f6f", accent = "#d0583a", teal = "#7fb8b0", yellow = "#d29f45", blue = "#7f9dbd", red = "#d64b4b" },
        light = { ground = "#e9e1cb", bar = "#dcd2b8", key = "#efe8d5", text = "#2b2721", muted = "#5f594d", accent = "#c0462a", teal = "#2f6e67", yellow = "#845b0f", blue = "#3f6185", red = "#a8342a" },
      }
      local function theme()
        local p = P[vim.o.background] or P.dark
        local function mode(c)
          return { a = { bg = c, fg = p.ground, gui = "bold" }, b = { bg = p.key, fg = p.text },
                   c = { bg = p.bar, fg = p.muted } }
        end
        local quiet = { bg = p.bar, fg = p.muted }
        return { normal = mode(p.accent), insert = mode(p.teal), visual = mode(p.yellow),
                 replace = mode(p.red), command = mode(p.blue), terminal = mode(p.teal),
                 inactive = { a = quiet, b = quiet, c = quiet } }
      end
      opts.options = opts.options or {}
      opts.options.theme = theme()
      vim.api.nvim_create_autocmd("ColorScheme", {
        group = vim.api.nvim_create_augroup("kawa_lualine", { clear = true }),
        callback = function()
          local ok, lualine = pcall(require, "lualine")
          if ok then
            opts.options.theme = theme()
            lualine.setup(opts)
          end
        end,
      })
    end,
  },
}
